import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import assert from "node:assert/strict";

// An explicit frozen baseline, never regenerated by a test or build.
const baselinePath = new URL("./presentation-baseline.json", import.meta.url);
const files = execFileSync("git", ["ls-files", "-z"], {
  encoding: "utf8",
  maxBuffer: 16 * 1024 * 1024,
})
  .split("\0")
  .filter(Boolean);
const protectedFiles = files.filter(
  (file) =>
    /\.(stories\.[cm]?[jt]sx?|mdx|contract\.json)$/.test(file) ||
    file.startsWith("public/") ||
    file.startsWith("app/fonts/") ||
    file === "nextjs-app/shared/styles/variables.css",
);
const hashes = protectedFiles.map((file) => [
  file,
  createHash("sha256").update(readFileSync(file)).digest("hex"),
]);
const indexPath = process.argv[3];
const index = JSON.parse(readFileSync(indexPath, "utf8"));
const catalogue = Object.values(index.entries)
  .map(({ id, title, name, type, importPath, tags }) => ({
    id,
    title,
    name,
    type,
    importPath,
    tags,
  }))
  .sort((a, b) => a.id.localeCompare(b.id));
if (process.argv[2] === "--capture") {
  writeFileSync(
    baselinePath,
    JSON.stringify(
      {
        commit: execFileSync("git", ["rev-parse", "HEAD"], {
          encoding: "utf8",
        }).trim(),
        hashes,
        catalogue,
      },
      null,
      2,
    ) + "\n",
  );
} else {
  const baseline = JSON.parse(readFileSync(baselinePath, "utf8"));
  assert.deepEqual(
    hashes,
    baseline.hashes,
    "Protected sources or branding assets changed",
  );
  assert.deepEqual(
    catalogue,
    baseline.catalogue,
    "Story IDs, titles, exports, tags or categories changed",
  );
}
console.log(
  `${catalogue.length} catalogue entries; ${hashes.length} protected source/asset hashes verified.`,
);
